<?php
session_start();require_once 'conexion.php';require_once 'auth.php';asegurarSistemaUsuarios($conexion);exigirRoles(array('ADMINISTRADOR'));
if (strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') {
    automacValidarCsrf(true);
}require_once 'schema_guard.php';
function dgE($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$mensajeAccion='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['accion']??'')==='desactivar_registro'){
    $tipo=(string)($_POST['tipo']??''); $id=(int)($_POST['id']??0);
    $permitidos=array(
      'accesorio'=>array('tabla'=>'accesorios_catalogo','id'=>'accesorio_id','set'=>"accesorio_activo='NO'"),
      'limite'=>array('tabla'=>'limites','id'=>'limite_id','set'=>"limite_activo='NO'"),
      'rescate'=>array('tabla'=>'rescates_componentes','id'=>'componente_id','set'=>"componente_activo='NO'"),
      'repuesto'=>array('tabla'=>'productos_repuestos','id'=>'producto_repuesto_id','set'=>'habilitado=0')
    );
    if($id>0 && isset($permitidos[$tipo])){
        $cfg=$permitidos[$tipo]; $sql="UPDATE `{$cfg['tabla']}` SET {$cfg['set']} WHERE `{$cfg['id']}`=? LIMIT 1";
        $st=$conexion->prepare($sql); if($st){$st->bind_param('i',$id);$st->execute();$st->close();$mensajeAccion='Registro desactivado. No se eliminó información histórica.';}
    }
}
$tablas=array('centrales','baterias','matriz_baterias','matriz_calculos','lista_precios','bejerman_listas','bejerman_productos','productos_repuestos','accesorios_catalogo','accesorios_control_acceso_reglas','accesorios_cable_mallado','accesorios_pesador_base','accesorios_pesador_frentes','accesorios_supervisor_reglas','limites','limites_paradas_tecnicos','rescates_opciones','rescates_componentes','cotizaciones','cotizaciones_detalle','cotizaciones_revisiones','cotizaciones_revisiones_detalle','pedidos','pedidos_detalle','pedidos_revisiones','pedidos_revisiones_detalle','numeracion_documentos','plantillas_controles','usuarios','cpus','equivalencias_codigos','schema_migrations');
$estadoTablas=array();foreach($tablas as $t)$estadoTablas[$t]=esquemaTablaExiste($conexion,$t);
$faltantes=array();

$criticos=array();
$agregarCritico=function($nombre,$ok,$detalle='')use(&$criticos){$criticos[]=array('nombre'=>$nombre,'ok'=>(bool)$ok,'detalle'=>$detalle);};
$rMig=$conexion->query("SELECT 1 FROM schema_migrations WHERE migration_id='v117_clex_dangelica_matriz_base' LIMIT 1");$agregarCritico('Migración v117 aplicada', $rMig&&$rMig->num_rows>0, 'Requerida por v118/v119.');
$rCpu=$conexion->query("SELECT c.cpu_name,b.cpu_name AS base FROM cpus c LEFT JOIN cpus b ON b.cpu_id=c.cpu_matriz_base_id WHERE c.cpu_name IN('A6220V5','A6300V4','A6700V2','CLEX','DANGELICA')");$map=array();if($rCpu)while($x=$rCpu->fetch_assoc())$map[$x['cpu_name']]=$x['base'];
$agregarCritico('CPUs vigentes y matrices base', ($map['A6220V5']??'')==='A6220V5'&&($map['A6300V4']??'')==='A6300V4'&&($map['A6700V2']??'')==='A6700V2'&&($map['CLEX']??'')==='A6300V4'&&($map['DANGELICA']??'')==='A6300V4', 'CLEX y DANGELICA deben conservar identidad y usar A6300V4 como matriz base.');
$rP3540=$conexion->query("SELECT 1 FROM lista_precios WHERE UPPER(TRIM(precios_codigo))='P3540' AND precios_costo>0 LIMIT 1");$agregarCritico('Código P3540 comunicación serie', $rP3540&&$rP3540->num_rows>0, 'Código Bejerman vigente para la placa de comunicación serie de Señalización.');
$rSigla=$conexion->query("SHOW INDEX FROM clientes WHERE Key_name='uq_clientes_codigo' AND Non_unique=0");$agregarCritico('Sigla de cliente única', $rSigla&&$rSigla->num_rows>0, 'clientes_codigo debe ser identificador único de negocio.');
$rLimC=$conexion->query("SELECT COUNT(*) c FROM limites_paradas_tecnicos WHERE activo='SI' AND modelo_control='CLEX'");$nLimC=$rLimC?(int)$rLimC->fetch_assoc()['c']:0;$rLimD=$conexion->query("SELECT COUNT(*) c FROM limites_paradas_tecnicos WHERE activo='SI' AND modelo_control LIKE 'CD2203%'");$nLimD=$rLimD?(int)$rLimD->fetch_assoc()['c']:0;$agregarCritico('Límites técnicos CLEX/DANGELICA', $nLimC>0&&$nLimD>0, 'CLEX: '.$nLimC.' reglas · DANGELICA/CD2203: '.$nLimD.' reglas.');
$rCod=$conexion->query("SELECT precios_codigo FROM lista_precios WHERE precios_codigo IN('A3700X','A3710X') AND precios_costo>0");$cod=array();if($rCod)while($x=$rCod->fetch_assoc())$cod[$x['precios_codigo']]=true;$agregarCritico('Adicionales control de acceso', !empty($cod['A3700X'])&&!empty($cod['A3710X']), 'Chip/Tarjeta usan A3700X; Teclado usa A3710X.');

$queries=array(
 'Accesorios directos'=>array('tipo'=>'accesorio','editar'=>'mantenimiento_accesorios.php','sql'=>"SELECT a.accesorio_id id,a.accesorio_codigo codigo,a.accesorio_nombre descripcion FROM accesorios_catalogo a LEFT JOIN lista_precios lp ON TRIM(lp.precios_codigo)=TRIM(a.accesorio_codigo) WHERE a.accesorio_activo='SI' AND a.accesorio_tipo='CODIGO_DIRECTO' AND a.accesorio_codigo IS NOT NULL AND (lp.precios_codigo IS NULL OR lp.precios_costo<=0)"),
 'Límites'=>array('tipo'=>'limite','editar'=>'mantenimiento_accesorios.php','sql'=>"SELECT l.limite_id id,l.limite_codigo codigo,l.limite_nombre descripcion FROM limites l LEFT JOIN lista_precios lp ON TRIM(lp.precios_codigo)=TRIM(l.limite_codigo) WHERE l.limite_activo='SI' AND (lp.precios_codigo IS NULL OR lp.precios_costo<=0)"),
 'Componentes de rescate'=>array('tipo'=>'rescate','editar'=>'mantenimiento_control.php?tab=baterias','sql'=>"SELECT rc.componente_id id,rc.componente_codigo codigo,CONCAT('Rescate #',rc.rescate_id) descripcion FROM rescates_componentes rc LEFT JOIN lista_precios lp ON TRIM(lp.precios_codigo)=TRIM(rc.componente_codigo) WHERE rc.componente_activo='SI' AND (lp.precios_codigo IS NULL OR lp.precios_costo<=0)"),
 'Repuestos habilitados'=>array('tipo'=>'repuesto','editar'=>'mantenimiento_repuestos.php','sql'=>"SELECT r.producto_repuesto_id id,r.codigo,r.descripcion FROM productos_repuestos r WHERE r.habilitado=1 AND COALESCE(r.costo_referencia,0)<=0 LIMIT 100")
);
foreach($queries as $grupo=>$cfg){$r=$conexion->query($cfg['sql']);if($r)while($f=$r->fetch_assoc())$faltantes[]=array('grupo'=>$grupo,'codigo'=>$f['codigo'],'descripcion'=>$f['descripcion'],'id'=>(int)$f['id'],'tipo'=>$cfg['tipo'],'editar'=>$cfg['editar']);}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diagnóstico de catálogos</title><style>body{font-family:Arial;background:#f4f7f8;color:#183142;margin:0}.wrap{max-width:1200px;margin:18px auto;padding:0 18px}.card{background:#fff;border:1px solid #dbe3e8;border-radius:12px;padding:16px;margin-bottom:16px}.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{font-size:12px;padding:5px 8px;border-radius:999px}.ok{background:#e7f7ee;color:#11603a}.bad{background:#fdecec;color:#9d2424}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:6px;border-bottom:1px solid #e2e8ec;text-align:left}th{background:#f6f9fa}.btn{display:inline-block;padding:6px 9px;border:0;border-radius:7px;background:#0f5f9c;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.danger{background:#a83636}.msg{padding:10px;border-radius:8px;background:#e7f7ee;color:#11603a;margin-bottom:12px}</style></head><body><?php require 'menu.php';?><main class="wrap"><h1>Diagnóstico de integridad</h1><section class="card"><h2>Esquema</h2><div class="chips"><?php foreach($estadoTablas as $t=>$ok):?><span class="chip <?=$ok?'ok':'bad'?>"><?=dgE($t)?> · <?=$ok?'OK':'FALTA'?></span><?php endforeach;?></div></section><section class="card"><h2>Compatibilidad crítica v119</h2><div class="chips"><?php foreach($criticos as $c):?><span class="chip <?=$c['ok']?'ok':'bad'?>" title="<?=dgE($c['detalle'])?>"><?=dgE($c['nombre'])?> · <?=$c['ok']?'OK':'REVISAR'?></span><?php endforeach;?></div><?php $fallosCriticos=array_values(array_filter($criticos,function($c){return !$c['ok'];})); if($fallosCriticos):?><table style="margin-top:12px"><thead><tr><th>Control</th><th>Detalle</th></tr></thead><tbody><?php foreach($fallosCriticos as $c):?><tr><td><strong><?=dgE($c['nombre'])?></strong></td><td><?=dgE($c['detalle'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><?php if($mensajeAccion):?><div class="msg"><?=dgE($mensajeAccion)?></div><?php endif;?><section class="card"><h2>Códigos activos sin precio válido</h2><?php if(!$faltantes):?><p class="ok" style="padding:10px;border-radius:8px">No se detectaron faltantes en los catálogos auditados.</p><?php else:?><table><thead><tr><th>Grupo</th><th>Código</th><th>Descripción</th><th>Acciones</th></tr></thead><tbody><?php foreach($faltantes as $f):?><tr><td><?=dgE($f['grupo'])?></td><td><strong><?=dgE($f['codigo'])?></strong></td><td><?=dgE($f['descripcion'])?></td><td><a class="btn" href="<?=dgE($f['editar'])?>">Corregir</a> <form method="post" style="display:inline" onsubmit="return confirm('¿Desactivar este registro para nuevas cotizaciones? No se borrarán históricos.');"><?= automacCsrfInput() ?><input type="hidden" name="accion" value="desactivar_registro"><input type="hidden" name="tipo" value="<?=dgE($f['tipo'])?>"><input type="hidden" name="id" value="<?=(int)$f['id']?>"><button class="btn danger" type="submit">Desactivar</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><section class="card"><p>Las acciones correctivas son conservadoras: permiten ir al mantenimiento de origen o desactivar el registro para nuevas cotizaciones. No se borran históricos ni registros desde el diagnóstico.</p></section></main></body></html>
